const PREFIXE = "[Hebdo]", ECHEANCE = "friday", TACHES = [["Revoir les mises à jour en attente dans MainWP", "MainWP", "Haute", "Tableau de bord Pilotage, bloc MainWP, ou MainWP > Mises à jour. Repérer les extensions abandonnées ou les mises à jour majeures."], ["Sauvegarder puis appliquer les mises à jour depuis la ligne du site principal", "MainWP", "Haute", "Sauvegarde de la base des réseaux concernés avant d'appliquer les mises à jour depuis la ligne du site principal dans MainWP."], ["Après une mise à jour du cœur WordPress : lancer « Mettre à jour le réseau » sur chaque réseau", "WordPress", "Normale", "MainWP ne met à jour que la base du site principal. Admin réseau > Tableau de bord > Mettre à jour le réseau (e-delmotte.info, echecs54.org, monclubdechecs.fr, ffechecs.fr, ffechecs.org)."], ["Enregistrer les mises à jour majeures comme changement dans iTop", "iTop", "Normale", "Gestion des changements > Nouveau changement (type Normal ou Routine), CIs concernés, plan de retour arrière."]];
const h = this.helpers, base = 'http://pilotage:8000/api/tasks';
const ouvertes = await h.httpRequest({ method: 'GET', url: base, json: true });
const now = new Date(), d = new Date(now);
if (ECHEANCE === 'friday') d.setDate(d.getDate() + ((5 - d.getDay() + 7) % 7));
if (ECHEANCE === 'month') { d.setMonth(d.getMonth() + 1, 0); }
if (ECHEANCE === 'quarter') { d.setMonth(Math.floor(d.getMonth() / 3) * 3 + 3, 0); }
const due = d.toISOString().slice(0, 10);
const crees = [];
for (const [titre, plateforme, priorite, detail] of TACHES) {
  const t = `${PREFIXE} ${titre}`;
  if (ouvertes.some(o => o.title === t)) continue;   // déjà dans la liste : pas de doublon
  await h.httpRequest({ method: 'POST', url: base, json: true, body: {
    title: t, client: 'e-delmotte (Eric Delmotte)', platform: plateforme, priority: priorite, status: 'À faire', due, detail } });
  crees.push(t);
}
return [{ json: { ok: true, crees } }];

